    fs.writeFileSync(path.join(destDir, 'SKILL.md'), '# Skill');
    fs.writeFileSync(path.join(destDir, 'examples/demo.md'), '# Old Demo');

    expect(determineState(makeEntry({ source: 'skills/canvas/**', destination: destDir }))).toBe(
      'outdated',
    );
  });
